// Plasma: three interfering waves, coloured with the dock pickers.
// Set Color 1 to red and Color 2 to yellow for the classic fire look.
vec3 c1 = u_col1;
vec3 c2 = u_col2;

// Scale of the pattern: raise 25.0 to pack the plasma tighter,
// lower it to stretch the shapes out.
float xx = u * 25.0;
float yy = v * 25.0;

// --- PLASMA ---
float v1 = sin(xx + yy);
float v2 = sin((xx * sin(yy/2.0)) + (yy * cos(xx/3.0)));

float cx = xx + 0.5 * sin(yy/5.0);
float cy = yy + 0.5 * cos(xx/3.0);
float v3 = sin(sqrt(100.0 * (cx*cx + cy*cy) + 1.0));

float vf = (v1 + v2 + v3) / 3.0;

// 'plasmaVal' e non 'tit': quel nome collide con le variabili iniettate.
float plasmaVal = vf * 0.5 + 0.5;

return mix(c1, c2, plasmaVal);
